#!/usr/bin/env python3
"""Generates reference/*.md from the canonical files in schema/. Do not edit the output by hand.

Run:  python3 tools/gen_reference.py          (writes the files)
      python3 tools/gen_reference.py --check  (exit 1 if the committed files are out of date)
"""
import json, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
SCHEMA = ROOT/"schema"; OUT = ROOT/"reference"
HEADER = "<!-- GENERATED by tools/gen_reference.py from schema/ . DO NOT EDIT BY HAND. -->\n\n"
def jl(n): return json.loads((SCHEMA/n).read_text(encoding="utf-8"))
def esc(s): return str(s).replace("|", "\\|").replace("\n", " ")
def table(head, rows): return "| " + " | ".join(head) + " |\n|" + "---|"*len(head) + "\n" + "".join("| " + " | ".join(esc(c) for c in r) + " |\n" for r in rows)
def fmt(v):
    if isinstance(v, (int, float)) and v >= 1024 and v % 1024 == 0 and v in (4096, 8192, 16384, 262144, 1048576, 4194304, 52428800, 1073741824):
        return f"{v:,} ({v/1048576:g} MiB)" if v >= 1048576 else f"{v:,} ({v/1024:g} KiB)"
    return f"{v:,}" if isinstance(v, int) else str(v)

def limits_md():
    d = jl("limits.json"); rows = []
    for x in sorted(d["limits"], key=lambda x: (x["category"], x["id"])):
        rows.append((x["id"], x["name"], fmt(x["value"]), x["unit"], x["status"], x["explained_in"], x["description"]))
    return HEADER + "# Limits registry\n\nSource: `schema/limits.json`. " + d["note"] + "\n\n" + table(("ID", "Name", "Value", "Unit", "Status", "Explained in", "Notes"), rows)

def errors_md():
    d = jl("error-codes.json"); out = HEADER + "# Error-code catalogue\n\nSource: `schema/error-codes.json`. " + d["naming"] + "\n\n"
    for fam, title in (("file", "File codes (Facilitator-facing)"), ("app", "Application codes (Facilitator-facing)"), ("protocol", "Protocol codes (participant-facing)")):
        rows = [(x["code"], x["http_status"] if x["http_status"] is not None else "-", x["retry"], "yes" if x["facilitator_alert"] else "no", x["stage"], x["description"], ", ".join(x["acceptance"])) for x in d["errors"] if x["family"] == fam]
        out += f"## {title}\n\n" + table(("Code", "HTTP", "Retry", "Alerts Facilitator", "Stage", "Meaning", "Acceptance scenarios"), rows) + "\n"
    return out

def rules_md():
    d = jl("validation-rules.json"); rows = [(x["id"], x["scope"], x["severity"], x["rule"], x["error_code"], x["stage"], ", ".join(x["acceptance"])) for x in d["rules"]]
    return HEADER + "# Validation-rule catalogue\n\nSource: `schema/validation-rules.json`. Rules a JSON Schema cannot express, plus the container and database rules applied to every file before it is opened.\n\n" + table(("ID", "Scope", "Severity", "Rule", "Error code", "Stage", "Acceptance scenarios"), rows)

def describe(node):
    c = []
    if "const" in node: c.append(f"must be `{json.dumps(node['const'])}`")
    if "enum" in node: c.append("one of " + ", ".join(f"`{e}`" for e in node["enum"]))
    if "pattern" in node: c.append(f"pattern `{node['pattern']}`")
    for k, label in (("minLength", "min length"), ("maxLength", "max length"), ("minimum", "min"), ("maximum", "max"), ("maxItems", "max items"), ("minItems", "min items")):
        if k in node: c.append(f"{label} {node[k]}")
    if node.get("uniqueItems"): c.append("unique items")
    if "default" in node: c.append(f"default `{json.dumps(node['default'])}`")
    return "; ".join(c)
def typ(node):
    t = node.get("type", "enum" if "enum" in node else "const" if "const" in node else "object")
    if t == "array" and isinstance(node.get("items"), dict): t = "array of " + str(node["items"].get("type", "object"))
    return ", ".join(t) if isinstance(t, list) else t
def walk(node, path, required, rows):
    for name, sub in node.get("properties", {}).items():
        p = f"{path}.{name}" if path else name
        rows.append((p, typ(sub), "yes" if name in node.get("required", []) else "no", describe(sub), sub.get("x-limit", ""), sub.get("description", "")))
        if sub.get("type") == "object": walk(sub, p, None, rows)
        elif sub.get("type") == "array" and isinstance(sub.get("items"), dict) and sub["items"].get("type") == "object": walk(sub["items"], p + "[]", None, rows)

def format_md():
    out = HEADER + "# File-format field reference\n\nSource: the schema files named below. Rules that a schema cannot express are in `validation-rules.md`. Unknown fields are rejected everywhere.\n\n"
    for f, title, entry in (("manifest.schema.json", "Manifest", "`manifest.json`"), ("theme.schema.json", "Theme", "`theme.json`"), ("settings.schema.json", "Settings", "`settings.json`"), ("slide.schema.json", "Slide envelope", "`slides/<id>.json`")):
        s = jl(f); rows = []; walk(s, "", None, rows)
        out += f"## {title} ({entry})\n\n" + esc(s.get("description", "")).replace("\\|", "|") + "\n\nSchema: `schema/" + f + "`\n\n" + table(("Field", "Type", "Required", "Constraints", "Limit ID", "Description"), rows) + "\n"
    return out

FILES = {"limits.md": limits_md, "error-codes.md": errors_md, "validation-rules.md": rules_md, "file-format.md": format_md}
if __name__ == "__main__":
    stale = []
    OUT.mkdir(exist_ok=True)
    for name, fn in FILES.items():
        text = fn(); p = OUT/name
        if "--check" in sys.argv:
            if not p.exists() or p.read_text(encoding="utf-8") != text: stale.append(name)
        else: p.write_text(text, encoding="utf-8")
    if "--check" in sys.argv:
        print("stale: " + ", ".join(stale) if stale else "reference files are up to date"); sys.exit(1 if stale else 0)
    print("wrote", ", ".join(FILES))
